import{_ as n,a0 as o,w as p,s as g,ao as r,I as a,x as i,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8","title":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器","tag":"201910","desc":""},"relativePath":"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),h={name:"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8.md"};function d(c,s,u,k,b,y){const e=o("Link");return p(),g("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-centos8-rhel8-中配置-rsyslog-服務器" tabindex="-1">如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器 <a class="header-anchor" href="#如何在-centos8-rhel8-中配置-rsyslog-服務器" aria-label="Permalink to “如何在 CentOS8/RHEL8 中配置 Rsyslog 服務器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/27/062908v4nnzgf7bhnplgvg.jpg" alt=""></p><p>Rsyslog 是一個自由開源的日誌記錄程序，在 CentOS 8 和 RHEL 8 系統上默認可用。它提供了一種從客户端節點到單箇中央服務器的“集中日誌”的簡單有效的方法。日誌集中化有兩個好處。首先，它簡化了日誌查看，因為系統管理員可以在一箇中心節點查看遠程服務器的所有日誌，而無需登錄每個客户端系統來檢查日誌。如果需要監視多台服務器，這將非常有用，其次，如果遠程客户端崩潰，你不用擔心丟失日誌，因為所有日誌都將保存在中心的 Rsyslog 服務器上。rsyslog 取代了僅支持 UDP 協議的 syslog。它以優異的功能擴展了基本的 syslog 協議，例如在傳輸日誌時支持 UDP 和 TCP 協議，增強的過濾功能以及靈活的配置選項。讓我們來探討如何在 CentOS 8 / RHEL 8 系統中配置 Rsyslog 服務器。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/configure-rsyslog-centos8-rhel8.jpg" alt="configure-rsyslog-centos8-rhel8"></p><h3 id="預先條件" tabindex="-1">預先條件 <a class="header-anchor" href="#預先條件" aria-label="Permalink to “預先條件”">​</a></h3><p>我們將搭建以下實驗環境來測試集中式日誌記錄過程：</p><ul><li>Rsyslog 服務器       CentOS 8 Minimal    IP 地址： 10.128.0.47</li><li>客户端系統          RHEL 8 Minimal      IP 地址： 10.128.0.48</li></ul><p>通過上面的設置，我們將演示如何設置 Rsyslog 服務器，然後配置客户端系統以將日誌發送到 Rsyslog 服務器進行監視。</p><p>讓我們開始！</p><h3 id="在-centos-8-上配置-rsyslog-服務器" tabindex="-1">在 CentOS 8 上配置 Rsyslog 服務器 <a class="header-anchor" href="#在-centos-8-上配置-rsyslog-服務器" aria-label="Permalink to “在 CentOS 8 上配置 Rsyslog 服務器”">​</a></h3><p>默認情況下，Rsyslog 已安裝在 CentOS 8 / RHEL 8 服務器上。要驗證 Rsyslog 的狀態，請通過 SSH 登錄並運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status rsyslog</span></span></code></pre></div><p>示例輸出:</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-service-status-centos8.jpg" alt="rsyslog-service-status-centos8"></p><p>如果由於某種原因 Rsyslog 不存在，那麼可以使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install rsyslog</span></span></code></pre></div><p>接下來，你需要修改 Rsyslog 配置文件中的一些設置。打開配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /etc/rsyslog.conf</span></span></code></pre></div><p>滾動並取消註釋下面的行，以允許通過 UDP 協議接收日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module(load=&quot;imudp&quot;) # needs to be done just once</span></span>
<span class="line"><span>input(type=&quot;imudp&quot; port=&quot;514&quot;)</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-conf-centos8-rhel8.jpg" alt="rsyslog-conf-centos8-rhel8"></p><p>同樣，如果你希望啓用 TCP rsyslog 接收，請取消註釋下面的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module(load=&quot;imtcp&quot;) # needs to be done just once</span></span>
<span class="line"><span>input(type=&quot;imtcp&quot; port=&quot;514&quot;)</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-conf-tcp-centos8-rhel8.jpg" alt="rsyslog-conf-tcp-centos8-rhel8"></p><p>保存並退出配置文件。</p><p>要從客户端系統接收日誌，我們需要在防火牆上打開 Rsyslog 默認端口 514。為此，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo firewall-cmd  --add-port=514/tcp  --zone=public  --permanent</span></span></code></pre></div><p>接下來，重新加載防火牆保存更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo firewall-cmd --reload</span></span></code></pre></div><p>示例輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/firewall-ports-rsyslog-centos8.jpg" alt="firewall-ports-rsyslog-centos8"></p><p>接下來，重啓 Rsyslog 服務器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart rsyslog</span></span></code></pre></div><p>要在啓動時運行 Rsyslog，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rsyslog</span></span></code></pre></div><p>要確認 Rsyslog 服務器正在監聽 514 端口，請使用 <code>netstat</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo netstat -pnltu</span></span></code></pre></div><p>示例輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/netstat-rsyslog-port-centos8.jpg" alt="netstat-rsyslog-port-centos8"></p><p>完美！我們已經成功配置了 Rsyslog 服務器來從客户端系統接收日誌。</p><p>要實時查看日誌消息，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/messages</span></span></code></pre></div><p>現在開始配置客户端系統。</p><h3 id="在-rhel-8-上配置客户端系統" tabindex="-1">在 RHEL 8 上配置客户端系統 <a class="header-anchor" href="#在-rhel-8-上配置客户端系統" aria-label="Permalink to “在 RHEL 8 上配置客户端系統”">​</a></h3><p>與 Rsyslog 服務器一樣，登錄並通過以下命令檢查 rsyslog 守護進程是否正在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status rsyslog</span></span></code></pre></div><p>示例輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/client-rsyslog-service-rhel8.jpg" alt="client-rsyslog-service-rhel8"></p><p>接下來，打開 rsyslog 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /etc/rsyslog.conf</span></span></code></pre></div><p>在文件末尾，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*.* @10.128.0.47:514           # Use @ for UDP protocol</span></span>
<span class="line"><span>*.* @@10.128.0.47:514          # Use @@ for TCP protocol</span></span></code></pre></div><p>保存並退出配置文件。就像 Rsyslog 服務器一樣，打開 514 端口，這是防火牆上的默認 Rsyslog 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd  --add-port=514/tcp  --zone=public  --permanent</span></span></code></pre></div><p>接下來，重新加載防火牆以保存更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>接下來，重啓 rsyslog 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart rsyslog</span></span></code></pre></div><p>要在啓動時運行 Rsyslog，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rsyslog</span></span></code></pre></div><h3 id="測試日誌記錄操作" tabindex="-1">測試日誌記錄操作 <a class="header-anchor" href="#測試日誌記錄操作" aria-label="Permalink to “測試日誌記錄操作”">​</a></h3><p>已經成功安裝並配置 Rsyslog 服務器和客户端後，就該驗證你的配置是否按預期運行了。</p><p>在客户端系統上，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># logger &quot;Hello guys! This is our first log&quot;</span></span></code></pre></div><p>現在進入 Rsyslog 服務器並運行以下命令來實時查看日誌消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/messages</span></span></code></pre></div><p>客户端系統上命令運行的輸出顯示在了 Rsyslog 服務器的日誌中，這意味着 Rsyslog 服務器正在接收來自客户端系統的日誌：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/centralize-logs-rsyslogs-centos8.jpg" alt="centralize-logs-rsyslogs-centos8"></p><p>就是這些了！我們成功設置了 Rsyslog 服務器來接收來自客户端系統的日誌信息。</p><hr>`,70)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.linuxtechi.com/configure-rsyslog-server-centos-8-rhel-8/"},{default:l(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/configure-rsyslog-server-centos-8-rhel-8/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.linuxtechi.com/author/james/"},{default:l(()=>[...s[2]||(s[2]=[i("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const v=n(h,[["render",d]]);export{C as __pageData,v as default};
